"""Build publication plots, a report, and native-state-only standalone replay."""
from pathlib import Path
import gzip, json, math, re, statistics, sys
from analyze159 import ROOT, DOC, read, save

def table(head,rows):
    return '\n'.join(['|'+'|'.join(head)+'|','|'+'|'.join(['---']*len(head))+'|']+['|'+'|'.join(str(x) for x in row)+'|' for row in rows])+'\n'

def plots(a,replay):
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    import numpy as np
    out=DOC/'plots';out.mkdir(exist_ok=True)
    plt.rcParams.update({'font.size':10,'axes.grid':True,'grid.alpha':.2})
    fig,ax=plt.subplots(figsize=(13,7))
    for r in replay['runs']:
        ss=r['samples'];ax.plot([q['x'] for q in ss],[q['y'] for q in ss],lw=.7,alpha=.7,label=r['scenario'])
    for g in replay['geometry']:
        for edge in ['Inner','Outer']:
            pts=g['Boundaries'][edge];ax.plot([q['X'] for q in pts],[q['Y'] for q in pts],color='black' if g['Name']=='progressive-b' else '#d27800',ls='-' if g['Name']=='progressive-b' else '--',lw=1.3,label=g['Name']+' '+edge)
    g=replay['geometry'][0]
    for key,color in [('ReferenceXY','#466e92'),('Line','#8d59ac')]:
        ax.plot([q[key]['X'] for q in g['Sections']],[q[key]['Y'] for q in g['Sections']],ls=':',lw=1,label='reference' if key=='ReferenceXY' else 'offset3.5 m')
    for name,i in [('I1',1),('O1',4),('I2',5),('O2',8)]:
        p=g['Joins'][i]['After']['ReferenceXY'];ax.scatter(p['X'],p['Y'],color='red',s=15);ax.annotate(name,(p['X'],p['Y']),xytext=(5,7),textcoords='offset points')
    ax.set(aspect='equal',xlabel='x [m]',ylabel='y [m]',title='Study159: exact original boundary polygons; all ten actual native paths')
    ax.legend(fontsize=7,ncol=4,loc='upper center',bbox_to_anchor=(.5,-.09));fig.tight_layout();fig.savefig(out/'geometry-xy.png',dpi=170);plt.close(fig)
    fig,axs=plt.subplots(3,1,figsize=(12,9),sharex=True)
    for g in replay['geometry']:
        ss=g['Sections'];s=[q['Reference'] for q in ss];axs[0].plot(s,[q['Width'] for q in ss],label=g['Name'])
    ss=replay['geometry'][0]['Sections'];s=[q['Reference'] for q in ss];axs[1].plot(s,[q['Curvature'] for q in ss],label='reference');axs[1].plot(s,[q['LineCurvature'] for q in ss],label='offset3.5 m')
    for speed in [38,60,90]:axs[2].plot(s,[(speed/3.6)**2*q['LineCurvature'] for q in ss],label=f'{speed} km/h')
    axs[2].axhline(1852.3389535074234/147,color='red',ls='--',label='absolute capacity / mass; no drive reserve')
    for ax in axs:
        for value in replay['geometry'][0]['Starts'][1:-1]:ax.axvline(value,color='gray',lw=.5,alpha=.5)
        ax.legend(fontsize=8,ncol=3)
    axs[0].set_ylabel('width [m]');axs[1].set_ylabel('curvature [1/m]');axs[2].set_ylabel('lateral acceleration [m/s²]');axs[2].set_xlabel('reference progress [m]');fig.tight_layout();fig.savefig(out/'geometry-profile.png',dpi=160);plt.close(fig)
    fig,axs=plt.subplots(4,1,figsize=(13,11),sharex=True)
    with gzip.open(DOC/'telemetry/validation-v6-new-0.csv.gz','rt') as f:
        import csv
        rows=[{k:float(v) if v not in ('','None') else None for k,v in r.items()} for r in csv.DictReader(f)]
    t=[q['time_s'] for q in rows]
    for r in replay['runs']:axs[0].plot([s['t'] for s in r['samples']],[s['speed'] for s in r['samples']],lw=.7,label=r['scenario'])
    axs[0].axhline(36,color='black',ls='--',label='generator target10m/s')
    for k in ['active_gas','requested_gas']:axs[1].plot(t,[q[k] for q in rows],lw=.7,label=k)
    for k in ['beta_deg','steering_deg']:axs[2].plot(t,[q[k] for q in rows],lw=.7,label=k)
    axs[3].plot(t,[q['yaw_rads'] for q in rows],lw=.7,label='yaw [rad/s]');axs[3].plot(t,[q['wheel_slip'] for q in rows],lw=.7,label='wheel slip ratio')
    for ax in axs:ax.legend(fontsize=7,ncol=4)
    axs[0].set_ylabel('speed [km/h]');axs[1].set_ylabel('throttle [0–1]');axs[2].set_ylabel('angle [deg]');axs[3].set_ylabel('rad/s / ratio');axs[3].set_xlabel('native time [s]');fig.tight_layout();fig.savefig(out/'native-profiles.png',dpi=160);plt.close(fig)
    fig,axs=plt.subplots(3,1,figsize=(13,9),sharex=True)
    for k in ['front_fx_body_N','front_fy_body_N','rear_fx_N','rear_fy_N']:axs[0].plot(t,[q[k] for q in rows],lw=.65,label=k)
    for k in ['front_util','rear_util','actual_grip_demand_fraction']:axs[1].plot(t,[q[k] for q in rows],lw=.7,label=k)
    axs[1].axhline(1,color='red',ls='--')
    for k in ['combustion_J','front_slip_loss_J','rear_lateral_slip_loss_J','rear_long_slip_loss_J','resistance_J']:
        axs[2].plot(t,np.cumsum([q[k]*q['dt_weight_s']/q['dt_s'] for q in rows])/1000,lw=1,label=k)
    for ax in axs:ax.legend(fontsize=7,ncol=3)
    axs[0].set_ylabel('force [N]');axs[1].set_ylabel('capacity fraction');axs[2].set_ylabel('cumulative work [kJ]');axs[2].set_xlabel('native time [s]');fig.tight_layout();fig.savefig(out/'forces-energy.png',dpi=160);plt.close(fig)
    fig,axs=plt.subplots(1,2,figsize=(13,5))
    for q in a['forecast_trials']:
        f=read(DOC/'forecasts'/f"{q['Label']}.json.gz");ss=f['Points'];ax=axs[0 if q['Fixture']=='rest' else 1]
        ax.plot([p['Time']-f['Initial']['Input']['Time'] for p in ss],[p['Rider']['Speed']*3.6 for p in ss],label=q['Variant']+(' / rejected' if not q['Legal'] else ''),lw=1)
    for ax,title in zip(axs,['From rest — diagnostic forecasts only','Saved-state straight — diagnostic forecasts only']):ax.set(title=title,xlabel='forecast duration [s]',ylabel='speed [km/h]');ax.legend(fontsize=7)
    fig.tight_layout();fig.savefig(out/'forecasts.png',dpi=160);plt.close(fig)
    fig,axs=plt.subplots(3,1,figsize=(12,8),sharex=True)
    for label in ['rest-base10','rest-speed12','rest-speed14']:
        f=read(DOC/'forecasts'/f'{label}.json.gz');ss=f['Points'];t=[p['Time'] for p in ss]
        axs[0].plot(t,[math.degrees(p['Rider']['SlideRadians']) for p in ss],label=label)
        axs[1].plot(t,[math.degrees(p['Steering']) for p in ss],label=label)
        axs[2].plot(t,[p['Rider']['Drive'] for p in ss],label=label)
    axs[0].axhline(45,color='red',ls='--',label='beta45 envelope')
    for ax in axs:ax.set_xlim(0,12);ax.legend(fontsize=8)
    axs[0].set_ylabel('beta [deg]');axs[1].set_ylabel('actuated steering [deg]');axs[2].set_ylabel('active throttle [0–1]');axs[2].set_xlabel('forecast time [s]');fig.tight_layout();fig.savefig(out/'forecast-control.png',dpi=160);plt.close(fig)
    fig,axs=plt.subplots(1,2,figsize=(13,5))
    for fraction in [.12,.5,.88]:
        rows=[q for q in a['equilibria'] if q['bend']==1 and q['fraction']==fraction and q['offset_m']==3.5 and q['local_equilibrium']]
        axs[0].plot([q['speed_kph'] for q in rows],[q['beta_deg'] for q in rows],marker='o',label=f'bend fraction {fraction}')
        axs[1].plot([q['speed_kph'] for q in rows],[q['gas'] for q in rows],marker='o',label=f'bend fraction {fraction}')
    axs[0].set(xlabel='speed [km/h]',ylabel='beta [deg]',title='Local equilibrium in original model; no stability claim');axs[1].set(xlabel='speed [km/h]',ylabel='throttle [0–1]',title='Local engine / clutch / wheel torque balance')
    for ax in axs:ax.legend(fontsize=8)
    fig.tight_layout();fig.savefig(out/'operating-points.png',dpi=160);plt.close(fig)

def report(a):
    nominal=a['native'][0];b=nominal['bends'];whole=nominal['all'];g=a['geometry'][0];cpu=a['cpu_profiles_s'];total=sum(cpu.values());parts=[];add=parts.append
    add('# Badanie #159 — geometria, potencjał fizyczny i ograniczenia AI\n')
    add('**PARTIAL: rozpoznano przyczyny wolnej jazdy; szybsza autonomia S3 nie została potwierdzona.** Baza to dokładny HEAD #158 / Draft PR #157: `'+a['base']+'`. Nowe narzędzie jest PROVISIONAL, wymaga jawnej komendy i pozostaje OFF. Brak merge. Fizyka, produkcja, oba historyczne profile toru i zamrożone dowody pozostają niezmienione.\n')
    add('## Odpowiedzi na osiem pytań\n')
    add('1. **Tor nie jest potwierdzoną rekonstrukcją współczesnej Motoareny.** #158 używa progressive-b: 318,778750 m referencji, proste62 m, identyczne łuki97,389375 m i symetryczne maksimum szerokości16,6 m. Progressive-c zmienia tylko szerokość na17/16,2 m; krzywa referencyjna, oba łuki i długość pozostają takie same. Nie odtwarza więc przebudowy drugiego łuku. Brak danych geodezyjnych i profilu poprzecznego.\n')
    add('2. **Model ma zapas prędkości powyżej37–38 km/h.** Lokalna prognoza ze stanu na prostej osiąga96,71 km/h po około58 m przy pełnym gazie. Oryginalne równania kontaktów, wału, sprzęgła i koła mają punkty lokalnej równowagi przy57,6 km/h w ciasnej części łuku i72 km/h w środku, na offsecie3,5 m. Są to prognoza i punkty równowagi, nie bezpieczne ukończenia łuków. Historyczne #148 potwierdza111,375 km/h na izolowanej prostej62 m od70 km/h oraz około148–151 km/h na długiej prostej w swoich warunkach. Nie wyznaczono globalnego Vmax obecnego biegu S.\n')
    add('3. **Bezpośrednie ograniczenie tempa to generator10 m/s i regulator prędkości.** `Settings158` deklaruje domyślnie12, ale `Generator158` jawnie przekazuje10 i CourseSeconds=1. Żądane przyspieszenie to `clamp((10−v)/1.2,−2,3)`. Działa także na prostych i odcina gaz po dojściu do celu. W25/50 wcześniej określonych stanów regulator żąda zwalniania i aktywny gaz daje ujemne przyspieszenie, podczas gdy identyczny stan przy gazie1 daje dodatnie. Jest to przyczynowy dowód lokalnej redukcji prędkości, nie certyfikat bezpiecznego pełnego gazu.\n')
    add('4. **Znacznie szybsze bezpieczne trzy okrążenia pozostają nierozstrzygnięte.** Próba samego celu12 m/s traci prześwit,14 m/s przekracza β45°. Pełny oryginalny planner12 m/s odmawia przed startem, ponieważ generator nie ma kompletnej legalnej rezerwy. Nie uruchamiano bezcelowej serii nowych światów. Wyniki #144/#148 są w starszym reżimie L i nie są certyfikacją S≥0,5 m.\n')
    add('5. **Obserwowane tempo ogranicza przede wszystkim AI, a niezawodność szybszego wariantu — interakcja AI, geometrii i dynamiki.** Budżet obu opon w nominalnych łukach jest wykorzystany średnio w około26–29%, daleko od stałej saturacji. Nie oznacza to niezależnej rezerwy dla dowolnego napędu i yaw. Zwiększenie samego gazu zmienia wheelspin, Fy i moment skręcający; granice geometrii oraz pełna rezerwa terminalna nadal obowiązują. Nie przypisujemy tym przyczynom arbitralnych procentów czasu.\n')
    add('6. **Wyższa prędkość wymaga spójnego β, skrętu, wheelspinu i momentu napędu.** W ciasnym lokalnym punkcie przy36→43,2→50,4→57,6 km/h równowagowe β rośnie0,87→1,88→3,34→5,97°, κ około0,032→0,039→0,055→0,096, a gaz0,080→0,101→0,135→0,200. Combined slip zabiera Fy przy rosnącym Fx. Punkty są chwilowo zrównoważone także dla oryginalnego sprzęgła, lecz nie wykazano ich stabilności ani osiągalności z zatrzymanego startu. Wysokie straty historycznego K1 nie są automatycznie bilansem #158.\n')
    add('7. **Największy koszt to pełne warunkowe kontynuacje.** Zapisany wyłączny profil dziesięciu biegów przypisuje im '+f"{cpu['conditional_continuations']/total*100:.2f}%"+' CPU profilowanego planowania. Niezależna certyfikacja pozostaje kosztowna i obowiązkowa. Samo generowanie nowych rezerw jest niewielką częścią tego profilu. Mikroprofil rozdziela prefiks0,24 s, inwersję Control158 i korektę Joint158; nie dodajemy go do pomiarów dawnych biegów.\n')
    add('8. **Następny PR: fizycznie spójny generator profilu prędkości i β, z istniejącą certyfikacją.** Na zamrożonym B wyznaczać wykonalne lokalne stany kontaktów i feed-forward yaw/β, przygotowywać wejście przed zmianą krzywizny, używać rzeczywistego aktuatora w inwersji i wspólnie korygować gaz oraz skręt. Parametry linii i prędkości mają generować propozycje w obecnym Runtime158; pełne13/9, niezależny provider i oryginalny świat pozostają bramką. Szczegółowy zakres znajduje się niżej.\n')
    add('## A. Źródła i geometria\n')
    add('Oficjalna [karta zespołu Ekstraligi, sezon2026](https://ekstraliga.pl/plan-minimum-czyli-utrzymanie-sie-mamy-na-wyciagniecie-reki-wypowiedzi-ewinner-apatora-torun-z-czetor/druzyny/1/2026/info) potwierdza318 m oraz12/12 m na prostych i17/16,2 m na łukach. [Podręcznik Ekstraliga Camp2023, s.6 PDF](https://cdn.speedwayekstraliga.pl/2023/06/ENG-Manual-Speedway-Ekstraliga-Camp-2023.pdf) potwierdza proste62 m i długość318 m, lecz podaje18 m na łukach. [Artykuł organizatora ligi](https://ekstraliga.pl/se/news/czy-podczas-pge-imme-im-zenona-plecha-padnie-nowy-rekord-toru) wyraźnie rozdziela początkowe325 m i318 m po przebudowie drugiego łuku przed sezonem2017. [Opis miejski](https://www.torun.pl/pl/sport-i-rekreacja/stadiony) nadal podaje325 m i18 m; traktujemy go jako starsze dane, mimo obecnej dostępności strony. Źródła sprawdzono2026-11-02. Nie uzgadniamy sprzecznych szerokości przez uśrednienie.\n')
    add(table(['Wielkość','B w #158','C istniejący','Współczesne dane'],[['Referencja / długość [m]','318,778750','318,778750','318; dokładne XY nieudostępnione'],['Proste [m]','35+27 / 62','35+27 / 62','62 / 62'],['Łuki [m]','97,389375 /97,389375','identyczne B','nieznany rozdział po przebudowie'],['Szerokość [m]','12 →16,6 /16,6','12 →17 /16,2','12 /17 /16,2'],['Minimalny R referencji [m]','około24,48','identyczny B','niepotwierdzony pomiar'],['Minimalny R offset3,5 [m]','około27,98','identyczny B','niepotwierdzony pomiar']]))
    add('Nominalne31 m nie jest stałym lokalnym promieniem profilu C2. Krzywizna ma rampę na pierwszych/ostatnich5% łuku i falowanie `1+0,2 cos(2πt)`: większe wymagania występują w częściach wejściowej i wyjściowej, a środek jest łagodniejszy. Trzy segmenty każdego łuku dzielą jego długość na równe części, ale nie są odrębnymi okręgami. Linia pomiarowa leży1 m od wewnętrznej granicy; rzeczywiste granice są przy offsecie−1 i width−1. Szerokość jest płynnie rozszerzana i zwężana kwintycznym smoothstepem. Nie znaleziono sztucznego zwężenia poniżej12 m ani skoku pozycji/kierunku/krzywizny na złączach. Gładkość konstrukcji nie potwierdza zgodności z obiektem.\n')
    add(f"Kontrola projekcja→XY→projekcja na0,1 m daje maksymalnie{g['roundtrip_reference_error_max_m']*1e6:.2f} µm błędu referencji i{g['roundtrip_offset_error_max_m']*1e6:.2f} µm offsetu w badanej linii3,5 m. Eksport przechowuje **dokładne wierzchołki poligonów** oryginalnego `CurveBoundaryAudit`, odczytane bez modyfikacji, a także próbki krzywej w double. Audytor odejmuje istniejące0,7 mm osłony cięciw i0,1 mm tolerancji numerycznej; nie zamieniono ich na dodatkową szerokość.\n")
    add('![XY w tej samej skali](plots/geometry-xy.png)\n\n![Profil szerokości i krzywizny](plots/geometry-profile.png)\n')
    add('Na C te same zapisane trajektorie nr5 i8 miałyby swept odpowiednio0,320489 i0,262811 m; pierwsze naruszenia występują przy61,98 i95,21 s. To audyt granic tych samych stanów, **nie** nowe biegi ani8/10 autonomicznych ukończeń C. Historyczne10/10 na B pozostaje bez zmian. Nie dodano nowego kandydata geometrycznego, ponieważ dostępne szerokości nie wyznaczają rzeczywistego przebiegu. Ewentualna rekonstrukcja318 m wymaga osobnej tożsamości, pomiarów, testów i osobnej walidacji.\n')
    add('## B. Fizyka i bilans energii\n')
    add('Oryginalny model: m147 kg, I52,72097 kg·m², silnik500cc z krzywą założoną w #116, statyczne µFz, koło i wał/sprzęgło #144. B=1852,338954 N, przód854,925697 N, tył997,413257 N; efektywne µ1,2845 jest parametrem modelu, bez kalibracji szutru. Opory40+0,20v² N, przełożenie9, sprawność0,94. Fizyka nie zawiera twardego ogranicznika37–38 km/h.\n')
    add(table(['Część łuku / offset3,5','Rmin [m]','ay przy38 [m/s²]','ay przy60','ay przy90','Granica skalarna [km/h]'],[[p['phase'],f"{p['min_line_radius_m']:.2f}",f"{p['lateral_demand_38_mps2']:.2f}",f"{p['lateral_demand_60_mps2']:.2f}",f"{p['lateral_demand_90_mps2']:.2f}",f"{p['scalar_no_drive_bound_kph']:.2f}"] for p in g['bends'][0]['phases']]))
    add('To konieczne granice `ay=v²κ`, `F=m·v²κ`, `v≤sqrt(B/(mκ))` dla lokalnej linii o stałym offsecie. Nie uwzględniają jednoczesnego Fx, momentu yaw, aktuatora, obrysu ani swept i nie są wykonalnym profilem jazdy. Dla zmiennej linii trzeba liczyć krzywiznę jej rzeczywistego XY, nie tylko road.Radius. Telemetria zawiera oba promienie i krzywiznę z natywnych zmian wektora prędkości. Przy90 km/h linia3,5 m w ciasnej części żąda około3284 N przy1852 N całkowitego budżetu. Nie wynika stąd niemożliwość dowolnej innej trajektorii.\n')
    add(table(['Nominalny #158','Cały bieg','Łuki','Proste'],[['Czas [s]',f"{whole['duration_s']:.3f}",f"{b['duration_s']:.3f}",f"{nominal['straights']['duration_s']:.3f}"],['Średnia prędkość [km/h]',f"{whole['mean_speed_kph']:.3f}",f"{b['mean_speed_kph']:.3f}",f"{nominal['straights']['mean_speed_kph']:.3f}"],['Przód średnia utilizacja',f"{whole['mean_front_util']:.3f}",f"{b['mean_front_util']:.3f}",f"{nominal['straights']['mean_front_util']:.3f}"],['Tył średnia utilizacja',f"{whole['mean_rear_util']:.3f}",f"{b['mean_rear_util']:.3f}",f"{nominal['straights']['mean_rear_util']:.3f}"],['Czas saturacji≥95% przód/tył [s]',f"{whole['front_saturated_s']:.3f}/{whole['rear_saturated_s']:.3f}",f"{b['front_saturated_s']:.3f}/{b['rear_saturated_s']:.3f}",'patrz analysis.json']]))
    add('Całobiegowe maksimum wheelspinu11,316 pojawia się podczas startu, przy małej prędkości mianownika. W łukach nominalnego maksimum jest0,644, średnia0,041. Nie należy przenosić maksimum startowego na sześć łuków. Pełny gaz nie oznacza natychmiast pełnej siły: skończone stany wału/koła i pasywne sprzęgło określają dostępny moment. Zamknięcie gazu nie jest dowodem ujemnego momentu; zapisujemy rzeczywisty znak momentu i bilans.\n')
    keys=[('Spalanie','combustion_J'),('Praca przodu w translacji','front_translation_J'),('Tył Fx w translacji','rear_drive_translation_J'),('Tył Fy w translacji','rear_lateral_translation_J'),('Opory w translacji','resistance_J'),('Zmiana energii translacji','translation_change_J'),('Strata poślizgu przodu','front_slip_loss_J'),('Strata boczna tyłu','rear_lateral_slip_loss_J'),('Wheelspin wzdłużny','rear_long_slip_loss_J'),('Ciepło sprzęgła','clutch_heat_J'),('Straty przekładni','transmission_loss_J'),('Straty łożyska','bearing_loss_J'),('Reszta całego bilansu','total_energy_residual_J')]
    add(table(['Nominalny bilans','Cały bieg [kJ]','Łuki [kJ]'],[[label,f"{whole['energy_J'][key]/1000:.6f}",f"{b['energy_J'][key]/1000:.6f}"] for label,key in keys]))
