def main():
    a=read(DOC/'analysis.json');replay=read(DOC/'native-replay.json.gz');plots(a,replay);report(a)
    template=(ROOT/'tools/geometry-speed-audit/replay159.html').read_text(encoding='utf-8')
    model=(ROOT/'tools/replay-viewer/study159-model.mjs').read_text(encoding='utf-8').replace('export ','')
    compact=json.dumps(replay,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
    (DOC/'Replay-159.html').write_text(template.replace('/*MODEL*/',model).replace('/*DATA*/',compact),encoding='utf-8')
    print('Rendered report,7 plots and standalone native replay')

if __name__=='__main__':main()
